"id":"verified-amplifier-deaf-bonce-hannibal-green-line-gl-700-1","category":"AMPLIFIER","brand":"Deaf Bonce","model":"Hannibal Green Line GL-700.1","isActive":true,"lifecycle":"ACTIVE","sourceType":"MANUFACTURER_CATALOG","sourceUrl":"https://hannibal.audio/"}]}'::jsonb AS data),
current AS (
 SELECT "id", COALESCE("catalogs",'{}'::jsonb) AS catalogs
 FROM "SiteSettings" WHERE "id"='default'
),
updated AS (
 SELECT current."id",
 jsonb_set(current.catalogs, '{componentModels}',
   COALESCE((
     SELECT jsonb_agg(item ORDER BY item->>'category',item->>'brand',item->>'model')
     FROM (
       SELECT DISTINCT ON (lower(item->>'category'),lower(item->>'brand'),lower(item->>'model')) item
       FROM (
         SELECT jsonb_array_elements(COALESCE(current.catalogs->'componentModels','[]'::jsonb)) item
         UNION ALL SELECT jsonb_array_elements(seed.data->'models') item
       ) raw
       ORDER BY lower(item->>'category'),lower(item->>'brand'),lower(item->>'model'),
                CASE WHEN item->>'lifecycle'='ACTIVE' AND item->>'sourceType'='MANUFACTURER_CATALOG' THEN 0 ELSE 1 END,
                CASE WHEN item->>'isActive'='true' THEN 0 ELSE 1 END
     ) deduped
   ), '[]'::jsonb), true) AS catalogs
 FROM current, seed
)
UPDATE "SiteSettings" s SET "catalogs"=updated.catalogs
FROM updated WHERE s."id"=updated."id";
